-- 4. global branding set (no assets yet; the app falls back to built-in branding)
insert into public.branding_sets(scope,version,assets,app_name,is_active)
  select 'global',1,'{}'::jsonb,'LazyBooks',true where not exists (select 1 from public.branding_sets where scope = 'global');

-- 5. first admin: create the user in Supabase Auth (dashboard, email + password) with this email, then this row links it. Safe to re-run.
insert into public.admins(user_id,email,role)
  select id, email, 'owner' from auth.users where lower(email) = lower('demo-admin@example.invalid')
  on conflict (user_id) do nothing;
